/* * Shim <modes.h> for patch on OS-9. * * OS-9's own modes.h defines S_IFMT (the file-type mask) and S_IFDIR, but has * no S_IFREG: RBF has only two kinds of object, so "regular file" is simply * "not a directory".  patch's inp.c tests ((mode & S_IFMT) & ~S_IFREG) to mean * "is this something other than a plain file", and with the definition below * that reduces to exactly the directory bit -- which is the right question on * this filesystem. * * Placed here rather than in the shared COMPAT directory so it shadows the * system header for patch alone. */#include "/dd/defs/modes.h"#ifndef S_IFREG#define S_IFREG (S_IFMT & ~S_IFDIR)#endif